const feathers = require('@feathersjs/feathers');
const express = require('@feathersjs/express');
const { Forbidden, NotFound } = require('@feathersjs/errors');
const mongooseService = require('feathers-mongoose');
const mongoose = require('mongoose');

const PrefsSchema = new mongoose.Schema({
  userId: String,
  smsAlerts: Boolean,
  marketingDigest: String
});
const PrefsModel = mongoose.model('NotificationPrefs', PrefsSchema);

const app = express(feathers());
app.use(express.json());
app.configure(express.rest());

app.use('/notification-preferences', mongooseService({
  Model: PrefsModel,
  paginate: { default: 10, max: 50 }
}));

app.service('notification-preferences').hooks({
  before: {
    update: [
      async (context) => {
        // Enforce that target document belongs to the authenticated user
        const existing = await context.service.get(context.id, {
          ...context.params,
          provider: undefined
        });

        if (!existing) {
          throw new NotFound('Preferences record not found');
        }

        if (existing.userId !== context.params.user._id.toString()) {
          throw new Forbidden('Cannot update preferences of another user');
        }

        const { marketingDigest } = context.data;
        if (marketingDigest && !['DAILY', 'WEEKLY', 'NEVER'].includes(marketingDigest)) {
          throw new Error('Invalid digest frequency option');
        }
        return context;
      }
    ]
  }
});
